// ========================================================
// academy-sendpulse-cleanup-expired
// Uses view v_sendpulse_buyer_list_mapping for classification
// ========================================================

const today = new Date();

// List config: all 9 families with active + ex-alunos IDs and vigencia
const LIST_CONFIG = {
  '641808': { name: 'formacao-ai-native-engineer', exListId: '644164', validityYears: 1 },
  '641807': { name: 'semana-aide',        exListId: '644165', validityYears: 1 },
  '641804': { name: 'comunidade-plumbers', exListId: '644166', validityYears: 1 },
  '641540': { name: 'spark-databricks',    exListId: '644167', validityYears: 2 },
  '647043': { name: 'bootcamp-aide',       exListId: '647048', validityYears: 1 },
  '647044': { name: 'combo-aide',          exListId: '647049', validityYears: 1 },
  '647045': { name: 'ai-data-engineer-pratica', exListId: '647050', validityYears: 1 },
  '647046': { name: 'academy-2-0',         exListId: '647051', validityYears: 1 },
  '647047': { name: 'dataship',            exListId: '647052', validityYears: 1 },
};

// Product title patterns -> Active list ID (more specific first)
const PRODUCT_PATTERNS = [
  { re: 'bootcamp.*ai data engineer|bootcamp \\| ai data engineer', listId: '647043' },
  { re: 'combo ai data engineer',                                    listId: '647044' },
  { re: 'ai data engineer na pr[a\u00e1]tica',                       listId: '647045' },
  { re: 'forma..o ai data engineer|formacao ai data engineer',       listId: '641808' },
  { re: 'semana ai data engineer|semana aide',                       listId: '641807' },
  { re: 'academy 2\\.0|comunidade academy',                          listId: '647046' },
  { re: 'dataship',                                                  listId: '647047' },
  { re: 'plumbers',                                                  listId: '641804' },
  { re: 'spark|databricks',                                          listId: '641540' },
];

function matchProduct(title) {
  const t = (title || '').toLowerCase();
  for (const p of PRODUCT_PATTERNS) {
    if (new RegExp(p.re, 'i').test(t)) return p.listId;
  }
  return null;
}

const rawItems = $input.all();
let subscriptions = [];
if (Array.isArray(rawItems[0]?.json)) {
  subscriptions = rawItems[0].json;
} else {
  subscriptions = rawItems.map(function(i) { return i.json; });
}

const parsed = [];
for (const s of subscriptions) {
  if (!s.email || String(s.email).trim() === '') continue;
  const email = String(s.email).toLowerCase().trim();
  const productTitle = s.product_title || '';
  const startDate = new Date(s.start_date);
  const status = s.subscription_status || '';
  const activeListId = matchProduct(productTitle);
  if (activeListId) {
    parsed.push({ email, productTitle, startDate, status, activeListId });
  }
}

const emailsByList = {};
for (const s of parsed) {
  const key = s.email + '|' + s.activeListId;
  if (!emailsByList[key]) {
    emailsByList[key] = { email: s.email, activeListId: s.activeListId, subs: [] };
  }
  emailsByList[key].subs.push(s);
}

const results = [];
const seen = new Set();
const keys = Object.keys(emailsByList);

for (let i = 0; i < keys.length; i++) {
  const data = emailsByList[keys[i]];
  const config = LIST_CONFIG[data.activeListId];
  if (!config) continue;

  let hasActive = false;
  for (let j = 0; j < data.subs.length; j++) {
    if (data.subs[j].status === 'upToDate' || data.subs[j].status === 'late') {
      hasActive = true;
      break;
    }
  }
  if (hasActive) continue;

  let maxTs = 0;
  for (let j = 0; j < data.subs.length; j++) {
    const ts = data.subs[j].startDate.getTime();
    if (ts > maxTs) maxTs = ts;
  }
  const expirationDate = new Date(maxTs);
  expirationDate.setFullYear(expirationDate.getFullYear() + config.validityYears);

  if (expirationDate < today) {
    const dedupKey = data.email + '|' + data.activeListId;
    if (!seen.has(dedupKey)) {
      seen.add(dedupKey);
      results.push({
        json: {
          email: data.email,
          active_list_id: data.activeListId,
          ex_alunos_list_id: config.exListId
        }
      });
    }
  }
}

if (results.length === 0) {
  return [{ json: { _empty: true, message: 'No expired subscribers to process', email: '' } }];
}

return results;

// Group expired emails by list for bulk API calls
const items = $input.all();
const removeByList = {};
const addByExList = {};

for (const item of items) {
  const d = item.json;
  if (!d.ex_alunos_list_id || !d.email) continue;
  if (!removeByList[d.active_list_id]) removeByList[d.active_list_id] = [];
  removeByList[d.active_list_id].push(d.email);
  if (!addByExList[d.ex_alunos_list_id]) addByExList[d.ex_alunos_list_id] = [];
  addByExList[d.ex_alunos_list_id].push(d.email);
}

const output = [];
for (const [listId, emails] of Object.entries(removeByList)) {
  output.push({ json: { action: 'remove', list_id: listId, emails_payload: JSON.stringify({ emails }), emails_count: emails.length } });
}
for (const [listId, emails] of Object.entries(addByExList)) {
  const addPayload = emails.map(e => ({ email: e }));
  output.push({ json: { action: 'add', list_id: listId, emails_payload: JSON.stringify({ emails: addPayload }), emails_count: emails.length } });
}
if (output.length === 0) return [{ json: { action: 'none', message: 'No valid subscribers to process' } }];
return output;
